439	        // 2) Memory cache
440	        {
441	            std::unique_lock lock(self->cacheMutex_);
442	            self->memoryCache_.erase(id);
443	        }
444	
445	        // Remote delete not implemented – ignore for now
446	        return std::variant<void, std::error_code>{};
447	    });
448	}
