451	// Sync
452	// ═════════════════════════════════════════════════════════════════════════════
453	inline void PaletteRepository::AddSyncListener(SyncListener cb)
454	{
455	    std::scoped_lock lock(listenerMutex_);
456	    syncListeners_.push_back(std::move(cb));
457	}
458	
459	inline void PaletteRepository::TriggerSync()
460	{
461	    if (syncInFlight_.exchange(true)) return; // already running
462	
463	    std::thread([self = shared_from_this()]()
464	    {
465	        bool ok = true;
466	
467	        // Gather candidates
468	        std::vector<Palette> pending;
469	        {
470	            std::shared_lock lock(self->cacheMutex_);
471	            for (const auto& [id, p] : self->memoryCache_)
472	                if (!p.isSynced) pending.push_back(p);
473	        }
474	
475	        // Push each palette
476	        for (auto& p : pending)
477	        {
478	            auto ec = self->pushRemote(p);
479	            if (!ec)
480	            {
481	                p.isSynced = true;
482	                {
483	                    std::unique_lock lock(self->cacheMutex_);
484	                    self->memoryCache_[p.id] = p;
485	                }
486	                // Persist new synced flag
487	                self->writeEncrypted(p);
488	            }
489	            else {
490	                ok = false;
491	            }
492	        }
493	
494	        // Notify listeners
495	        {
496	            std::scoped_lock lock(self->listenerMutex_);
497	            for (auto& cb : self->syncListeners_)
498	                try { cb(ok); } catch (...) { /* ignore */ }
499	        }
500	
501	        self->syncInFlight_.store(false);
502	    }).detach();
503	}
