151	// EventBus – thread-safe Observer pattern hub
152	// ============================================================================
153	class SubscriptionToken; // fwd
154	
155	class EventBus : public std::enable_shared_from_this<EventBus>
156	{
157	public:
158	    using Callback = std::function<void(const CreativeEvent&)>;
159	
160	    static std::shared_ptr<EventBus> instance()
161	    {
162	        static std::shared_ptr<EventBus> s_instance{new EventBus};
163	        return s_instance;
164	    }
165	
166	    // Subscribe to a specific event type; returns RAII token. Thread-safe.
167	    SubscriptionToken subscribe(CreativeEventType type, Callback cb);
168	
169	    // Publish an event to all subscribers of its type. Non-blocking.
170	    void publish(const CreativeEvent& ev) const
171	    {
172	        std::shared_lock rlock(m_mtx);
173	        auto it = m_observers.find(ev.type);
174	        if (it == m_observers.end())
175	            return;
176	
177	        // copy observers to avoid holding lock while user code executes
178	        auto observers = it->second;
179	        rlock.unlock();
180	
181	        for (const auto& weakCb : observers)
182	            if (auto cb = weakCb.lock(); cb)
183	                (*cb)(ev);
184	    }
185	
186	    // -- internal, used by SubscriptionToken
187	    void _unsubscribe(CreativeEventType type, std::size_t key)
188	    {
189	        std::unique_lock wlock(m_mtx);
190	        auto it = m_observers.find(type);
191	        if (it == m_observers.end())
192	            return;
193	        it->second.erase(
194	            std::remove_if(it->second.begin(),
195	                           it->second.end(),
196	                           [&](const WeakWrapper& w){
197	                               return w.key == key;
198	                           }),
199	            it->second.end());
200	    }
201	
202	private:
203	    EventBus()  = default;
204	    ~EventBus() = default;
205	
206	    struct CallbackWrapper
207	    {
208	        std::size_t             key;    // unique within type
209	        Callback                func;
210	
211	        void operator()(const CreativeEvent& ev) const
212	        {
213	            func(ev);
214	        }
215	    };
216	
217	    struct WeakWrapper
218	    {
219	        std::size_t                   key{};
220	        std::weak_ptr<CallbackWrapper> ptr;
221	
222	        WeakWrapper(std::size_t k, const std::shared_ptr<CallbackWrapper>& p)
223	            : key(k), ptr(p)
224	        {}
225	
226	        std::weak_ptr<CallbackWrapper> lock() const noexcept { return ptr; }
227	    };
228	
229	    mutable std::shared_mutex  m_mtx;
230	    mutable std::unordered_map<CreativeEventType, std::vector<WeakWrapper>> m_observers;
231	    std::atomic<std::size_t>   m_uid{0};
232	};
