234	// ============================================================================
235	// SubscriptionToken – RAII handle that auto-unsubscribes
236	// ============================================================================
237	class SubscriptionToken
238	{
239	public:
240	    SubscriptionToken() = default;
241	
242	    SubscriptionToken(std::weak_ptr<EventBus> bus,
243	                      CreativeEventType type,
244	                      std::size_t key)
245	        : m_bus(std::move(bus))
246	        , m_type(type)
247	        , m_key(key)
248	    {}
249	
250	    SubscriptionToken(const SubscriptionToken&) = delete;
251	    SubscriptionToken& operator=(const SubscriptionToken&) = delete;
252	
253	    SubscriptionToken(SubscriptionToken&& other) noexcept
254	    { *this = std::move(other); }
255	
256	    SubscriptionToken& operator=(SubscriptionToken&& other) noexcept
257	    {
258	        if (this == &other) return *this;
259	        unsubscribe();          // unsubscribe existing
260	        m_bus  = std::move(other.m_bus);
261	        m_type = other.m_type;
262	        m_key  = other.m_key;
263	        other.m_key = 0;
264	        return *this;
265	    }
266	
267	    ~SubscriptionToken()
268	    {
269	        unsubscribe();
270	    }
271	
272	    void unsubscribe() noexcept
273	    {
274	        if (m_key == 0) return;     // already unsubscribed / moved
275	        if (auto bus = m_bus.lock(); bus)
276	            bus->_unsubscribe(m_type, m_key);
277	        m_key = 0;
278	    }
279	
280	    explicit operator bool() const noexcept
281	    { return m_key != 0; }
282	
283	private:
284	    std::weak_ptr<EventBus> m_bus;
285	    CreativeEventType       m_type{CreativeEventType::Unknown};
286	    std::size_t             m_key{0};
287	};
288	
289	// EventBus::subscribe implementation (depends on SubscriptionToken definition)
290	inline SubscriptionToken EventBus::subscribe(CreativeEventType type, Callback cb)
291	{
292	    if (!cb)
293	        throw DomainError("EventBus::subscribe – callback must be valid");
294	
295	    auto wrapper = std::make_shared<CallbackWrapper>();
296	    wrapper->key = ++m_uid;
297	    wrapper->func = std::move(cb);
298	
299	    {
300	        std::unique_lock wlock(m_mtx);
301	        m_observers[type].emplace_back(wrapper->key, wrapper);
302	    }
303	
304	    return SubscriptionToken{weak_from_this(), type, wrapper->key};
305	}
