65	// -------------------------------------------------------------------------------------------------
66	// Simple Event Bus — type-safe, thread-safe, header-only
67	// -------------------------------------------------------------------------------------------------
68	
69	class EventBus
70	{
71	public:
72	    /** Subscription token, used for unsubscription **/
73	    class Token
74	    {
75	        friend class EventBus;
76	        std::type_index type_;
77	        std::size_t      id_;
78	
79	        Token(std::type_index type, std::size_t id) : type_(type), id_(id) {}
80	
81	    public:
82	        Token()                          = default;
83	        Token(const Token&)              = default;
84	        Token& operator=(const Token&)   = default;
85	        Token(Token&&) noexcept          = default;
86	        Token& operator=(Token&&)        = default;
87	        [[nodiscard]] bool valid() const { return id_ != 0; }
88	    };
89	
90	    template <typename Event>
91	    using Callback = std::function<void(const Event&)>;
92	
93	    /**
94	     * Subscribe to a particular event type.
95	     * @return Token that can later be used to unsubscribe.
96	     */
97	    template <typename Event>
98	    Token subscribe(Callback<Event> cb)
99	    {
100	        const std::type_index key = typeid(Event);
101	
102	        std::unique_lock lock(mutex_);
103	        auto&            vec = subscribers_[key];
104	
105	        const std::size_t id = ++uid_;
106	        vec.emplace_back(id, [fn = std::move(cb)](const auto& anyEvent) {
107	            fn(static_cast<const Event&>(anyEvent));
108	        });
109	
110	        return Token { key, id };
111	    }
112	
113	    /** Unsubscribe via token. No-op if token is invalid or already removed. */
114	    void unsubscribe(Token token)
115	    {
116	        std::unique_lock lock(mutex_);
117	        auto it = subscribers_.find(token.type_);
118	        if (it == subscribers_.end())
119	            return;
120	
121	        auto& vec = it->second;
122	        vec.erase(std::remove_if(vec.begin(), vec.end(),
123	                                 [&token](const Subscriber& s) { return s.id == token.id_; }),
124	                  vec.end());
125	    }
126	
127	    /** Publish an event to all interested subscribers. */
128	    template <typename Event>
129	    void post(const Event& event) const
130	    {
131	        std::unique_lock lock(mutex_);
132	        auto it = subscribers_.find(typeid(Event));
133	        if (it == subscribers_.end())
134	            return;
135	
136	        // Copy the vector, then dispatch outside the lock to avoid deadlocks
137	        auto vec = it->second;
138	        lock.unlock();
139	
140	        for (auto& sub : vec)
141	        {
142	            // Catch all exceptions so one faulty subscriber
143	            // doesn’t bring down the bus.
144	            try
145	            {
146	                sub.cb(event);
147	            }
148	            catch (const std::exception& ex)
149	            {
150	                std::cerr << "[EventBus] subscriber threw: " << ex.what() << '\n';
151	            }
152	            catch (...)
153	            {
154	                std::cerr << "[EventBus] subscriber threw unknown exception\n";
155	            }
156	        }
157	    }
158	
159	private:
160	    struct Subscriber
161	    {
162	        std::size_t                                 id;
163	        std::function<void(const void& /*Event*/)>  cb;
164	    };
165	
166	    mutable std::mutex                                                mutex_;
167	    mutable std::unordered_map<std::type_index, std::vector<Subscriber>> subscribers_;
168	    std::atomic_size_t                                                uid_ { 0 };
169	};
