336	{
337	public:
338	    FakeAudioSensorAdapter(EventBus& bus, std::chrono::milliseconds period)
339	        : bus_(bus)
340	        , period_(period)
341	    {
342	    }
343	
344	    void start()
345	    {
346	        running_ = true;
347	        thr_ = std::thread([this] { run(); });
348	    }
349	
350	    void stop()
351	    {
352	        running_ = false;
353	        cv_.notify_all();
354	        if (thr_.joinable())
