364	        std::uniform_real_distribution<float> ampDist(0.0F, 1.0F);
365	
366	        std::unique_lock lock(m_);
367	        while (running_)
368	        {
369	            cv_.wait_for(lock, period_, [this] { return !running_; });
370	            if (!running_)
371	                break;
372	
373	            AudioPeakEvent ev;
374	            ev.amplitude = ampDist(rng);
375	            bus_.post(ev);
376	        }
377	    }
378	
379	    EventBus&                    bus_;
380	    std::chrono::milliseconds    period_;
381	    std::atomic_bool             running_ { false };
382	    std::thread                  thr_;
383	    std::mutex                   m_;
384	    std::condition_variable      cv_;
