27	// Forward declarations to keep compile-time dependencies low.
28	// Concrete definitions live in `core/events`.
29	struct CreativeEvent;
30	
31	class IEventBus
32	{
33	public:
34	    virtual ~IEventBus() = default;
35	
36	    /**
37	     * Push an event to listeners.  Implementations must guarantee that `post`
38	     * is non-blocking and thread-safe; queueing is the preferred strategy.
39	     */
40	    virtual void post(const CreativeEvent& event) = 0;
41	};
42	} // namespace palettepulse::core
43	
44	namespace palettepulse::platform
45	{
46	
47	/**
48	 * PlatformBridge
49	 *
50	 * Thread-safe singleton that receives raw platform sensor signals and converts
51	 * them into high-level CreativeEvents.  All heavy-weight signal processing
52	 * (FFT, color clustering, beat detection) is delegated to dedicated services
53	 * further down the pipeline; the bridge limits itself to basic validation and
54	 * event normalization.
55	 */
56	class PlatformBridge final
57	{
58	public:
59	    using Clock      = std::chrono::system_clock;
60	    using TimePoint  = Clock::time_point;
61	    using ErrorCb    = std::function<void(const std::string&)>;
62	
63	    /**
64	     * Retrieve the global instance.
65	     * Safe to call from any thread at any point in the app lifecycle.
66	     */
67	    static PlatformBridge& instance();
68	
69	    PlatformBridge(const PlatformBridge&)            = delete;
70	    PlatformBridge& operator=(const PlatformBridge&) = delete;
71	    PlatformBridge(PlatformBridge&&)                 = delete;
72	    PlatformBridge& operator=(PlatformBridge&&)      = delete;
73	
74	    /**
75	     * One-time initialization. Must be called before the first sensor callback
76	     * reaches the bridge (e.g. in `Application.onCreate` or `AppDelegate`).
77	     * Subsequent calls are ignored.
78	     */
79	    void initialize(std::shared_ptr<core::IEventBus> eventBus) noexcept;
80	
81	    /**
82	     * Release resources.  Shuts down internal queues if present.
83	     * Safe to call multiple times (idempotent).
84	     */
85	    void shutdown() noexcept;
86	
87	    //-------------------------------------------------------
88	    // Sensor injection API (called by platform glue code)
89	    //-------------------------------------------------------
90	
91	    /**
92	     * Accelerometer update
93	     *  - Units: meters / second²
94	     */
95	    void onAccelerometerChanged(float x,
96	                                float y,
97	                                float z,
98	                                TimePoint timestamp = Clock::now()) noexcept;
99	
100	    /**
101	     * Microphone peak (RMS) in decibels.
102	     */
103	    void onAudioPeakDetected(float rmsDb,
104	                             TimePoint timestamp = Clock::now()) noexcept;
105	
106	    /**
107	     * RGBA frame captured from the camera.
108	     *
109	     * The buffer must be Base64 encoded to decouple memory ownership between
110	     * managed (Swift/Kotlin) and native code.  The payload is *not* decoded
111	     * inside the bridge – we forward it to the image-processing service which
112	     * handles GPU-friendly decoding.
113	     */
114	    void onFrameCaptured(std::string  rgbaFrameBase64,
115	                         std::uint32_t width,
116	                         std::uint32_t height,
117	                         TimePoint    timestamp = Clock::now()) noexcept;
118	
119	    //-------------------------------------------------------
120	    // Error handling
121	    //-------------------------------------------------------
122	
123	    /**
124	     * Register or replace an error callback. Pass `nullptr` to clear.
125	     * The callback is always executed on the *calling* thread.
126	     */
127	    void setErrorCallback(ErrorCb cb) noexcept;
128	
129	private:
130	    PlatformBridge() = default;
131	    ~PlatformBridge() = default;
132	
133	    //-------------------------------------------------------
134	    // Internal helpers
135	    //-------------------------------------------------------
136	    void ensureInitialized(const char* callsite);
137	    void dispatch(core::CreativeEvent&& evt) noexcept;
138	    void reportError(const std::string& msg) noexcept;
139	
140	    //-------------------------------------------------------
141	    // State
142	    //-------------------------------------------------------
143	    std::mutex                         m_mutex;
144	    std::shared_ptr<core::IEventBus>   m_eventBus;
145	    ErrorCb                            m_errorCb;
146	    std::atomic_bool                   m_initialized{false};
147	};
148	
149	//==============================================================================
150	//                              Implementation
151	//==============================================================================
152	
153	#include <stdexcept>
154	
155	namespace palettepulse::platform
156	{
157	inline PlatformBridge& PlatformBridge::instance()
158	{
159	    static PlatformBridge inst;
160	    return inst;
161	}
162	
163	inline void PlatformBridge::initialize(std::shared_ptr<core::IEventBus> eventBus) noexcept
164	{
165	    if (!eventBus)
166	    {
167	        reportError("PlatformBridge::initialize called with null event bus");
168	        return;
169	    }
170	
171	    std::scoped_lock lk{m_mutex};
172	    if (!m_initialized.exchange(true))
173	    {
174	        m_eventBus = std::move(eventBus);
175	    }
176	}
177	
178	inline void PlatformBridge::shutdown() noexcept
179	{
180	    std::scoped_lock lk{m_mutex};
181	    m_eventBus.reset();
182	    m_initialized = false;
183	}
184	
185	inline void PlatformBridge::setErrorCallback(ErrorCb cb) noexcept
186	{
187	    std::scoped_lock lk{m_mutex};
188	    m_errorCb = std::move(cb);
189	}
190	
191	//-------------------------------------------------------
192	// Sensor events
193	//-------------------------------------------------------
194	
195	inline void PlatformBridge::onAccelerometerChanged(float     x,
196	                                                   float     y,
197	                                                   float     z,
198	                                                   TimePoint ts) noexcept
199	{
200	    ensureInitialized(__func__);
201	
202	    // Basic sanity check – ignore obviously bogus values
203	    if (!std::isfinite(x) || !std::isfinite(y) || !std::isfinite(z))
204	    {
205	        reportError("Accelerometer values not finite");
206	        return;
207	    }
208	
209	    core::CreativeEvent evt{/* ... populate with normalized acceleration ... */};
210	    // Example only – actual members are defined in CreativeEvent
211	    // evt.type        = CreativeEventType::ACCELEROMETER;
212	    // evt.accel.x     = x;
213	    // evt.accel.y     = y;
214	    // evt.accel.z     = z;
215	    // evt.timestampNs = std::chrono::duration_cast<std::chrono::nanoseconds>(
216	    //                      ts.time_since_epoch())
217	    //                      .count();
218	
219	    dispatch(std::move(evt));
220	}
221	
222	inline void PlatformBridge::onAudioPeakDetected(float rmsDb, TimePoint ts) noexcept
223	{
224	    ensureInitialized(__func__);
225	
226	    if (!std::isfinite(rmsDb))
227	    {
228	        reportError("Audio peak value not finite");
229	        return;
230	    }
231	
232	    core::CreativeEvent evt{/* ... populate with audio peak ... */};
233	    dispatch(std::move(evt));
234	}
235	
236	inline void PlatformBridge::onFrameCaptured(std::string  rgbaFrameBase64,
237	                                            std::uint32_t width,
238	                                            std::uint32_t height,
239	                                            TimePoint     ts) noexcept
240	{
241	    ensureInitialized(__func__);
242	
243	    if (rgbaFrameBase64.empty() || width == 0 || height == 0)
244	    {
245	        reportError("Invalid frame captured (empty buffer or zero dimensions)");
246	        return;
247	    }
248	
249	    core::CreativeEvent evt{/* ... populate with image data ... */};
250	    dispatch(std::move(evt));
251	}
252	
253	//-------------------------------------------------------
254	// Internals
255	//-------------------------------------------------------
256	
257	inline void PlatformBridge::ensureInitialized(const char* callsite)
258	{
259	    if (m_initialized.load(std::memory_order_acquire))
260	        return;
261	
262	    std::string msg = std::string("PlatformBridge used before initialize: ") + callsite;
263	    reportError(msg);
264	    throw std::runtime_error(msg);
265	}
266	
267	inline void PlatformBridge::dispatch(core::CreativeEvent&& evt) noexcept
268	{
269	    std::shared_ptr<core::IEventBus> bus;
270	    {
271	        std::scoped_lock lk{m_mutex};
272	        bus = m_eventBus;
273	    }
274	
275	    if (bus)
276	    {
277	        bus->post(evt);
278	    }
279	    else
280	    {
281	        reportError("Event bus is null during dispatch");
282	    }
283	}
284	
285	inline void PlatformBridge::reportError(const std::string& msg) noexcept
286	{
287	    ErrorCb cb;
288	    {
289	        std::scoped_lock lk{m_mutex};
290	        cb = m_errorCb;
291	    }
292	    if (cb)
293	        cb(msg);
294	}
295	
296	} // namespace palettepulse::platform

