58	class ScopedTimer
59	{
60	public:
61	    explicit ScopedTimer(std::string label) noexcept
62	        : _label(std::move(label)),
63	          _start(std::chrono::steady_clock::now()) {}
64	
65	    ~ScopedTimer() noexcept
66	    {
67	        try
68	        {
69	            const auto end   = std::chrono::steady_clock::now();
70	            const auto delta =
71	                std::chrono::duration_cast<std::chrono::milliseconds>(end - _start)
72	                    .count();
73	            if (_logger) { _logger(_label, delta); }
74	        }
75	        catch (...) {}    // Never throw from a destructor.
76	    }
77	
78	    using Logger = std::function<void (const std::string&, std::int64_t)>;
79	
80	    static void setLogger(Logger logger) { _logger = std::move(logger); }
81	
82	private:
83	    std::string                                   _label;
84	    std::chrono::steady_clock::time_point         _start;
85	    static inline Logger                          _logger = nullptr;
86	};
