91	 * Responsibilities:
92	 *  1. Own the sensor life-cycle (start/stop).
93	 *  2. Spawn a worker thread that captures raw data and posts CreativeEvents.
94	 *  3. Provide thread-safe publish() for derived classes.
95	 */
96	class SensorAdapter : public std::enable_shared_from_this<SensorAdapter>
97	{
98	public:
99	    /**
100	     * Construct a SensorAdapter.
101	     *
102	     * @param eventBus Weak reference to the system EventBus.
103	     * @param type     Concrete sensor type the adapter represents.
104	     */
105	    explicit SensorAdapter(std::weak_ptr<core::EventBus> eventBus,
106	                           SensorType                     type   = SensorType::Unknown) noexcept
107	        : _eventBus(std::move(eventBus))
108	        , _type(type)
109	    {}
110	
111	    virtual ~SensorAdapter() noexcept
112	    {
113	        // Ensure thread joins before destruction.
114	        try { stop(); }
115	        catch (...) { /* swallow – leaving scope */ }
116	    }
117	
118	    /* Non-copyable, movable */
119	    SensorAdapter(const SensorAdapter&)            = delete;
120	    SensorAdapter& operator=(const SensorAdapter&) = delete;
121	    SensorAdapter(SensorAdapter&&)                 = delete;
122	    SensorAdapter& operator=(SensorAdapter&&)      = delete;
123	
124	    /**
125	     * Starts the dedicated capture thread (idempotent).
126	     * Throws std::runtime_error if already running or cannot start.
127	     */
128	    void start()
129	    {
130	        std::scoped_lock lk(_startStopMutex);
131	        if (_running.load(std::memory_order_acquire))
132	        {
133	            throw std::runtime_error("SensorAdapter already running");
134	        }
135	
136	        _running.store(true, std::memory_order_release);
137	        _worker = std::thread(&SensorAdapter::run, this);
138	    }
139	
140	    /**
141	     * Requests the thread to stop and waits for it to join (idempotent).
142	     * Never throws.
143	     */
144	    void stop() noexcept
145	    {
146	        {
147	            std::scoped_lock lk(_startStopMutex);
148	            if (!_running.exchange(false, std::memory_order_acq_rel)) { return; }
149	        }
150	
151	        if (_worker.joinable())
152	        {
153	            try { _worker.join(); }
154	            catch (...) { /* swallow – destructor safe */ }
155	        }
156	    }
157	
158	    /**
159	     * True if capture thread is alive.
160	     */
161	    [[nodiscard]] bool isRunning() const noexcept
162	    {
163	        return _running.load(std::memory_order_acquire);
164	    }
