177	    /**
178	     * Derived classes implement this method. It must:
179	     *   1. Poll / subscribe to platform sensor APIs.
180	     *   2. Convert raw data into CreativeEvent objects.
181	     *   3. Call publish(event) for each event.
182	     *
183	     * The loop MUST quit promptly when shouldContinue() returns false.
184	     */
185	    virtual void captureLoop() = 0;
186	
187	    /**
188	     * Sends an event to the EventBus if still valid.
189	     */
190	    void publish(core::CreativeEvent&& event);
191	
192	    /**
193	     * Check if the adapter should keep running.
194	     */
195	    [[nodiscard]] bool shouldContinue() const noexcept
196	    {
