201	    /**
202	     * Internal trampoline for std::thread.
203	     * Adds basic exception handling and perf logging.
204	     */
205	    void run() noexcept
206	    {
207	        const ScopedTimer timer("SensorAdapter::" + name() + "::captureLoop");
208	
209	        try
