348	inline auto PaletteRepository::Save(Palette palette) -> ResultFuture<PaletteId>
349	{
350	    return std::async(std::launch::async, [self = shared_from_this(), palette = std::move(palette)]() mutable
351	    {
352	        // 1) Write to disk
353	        if (auto ec = self->writeEncrypted(palette); ec)
354	            return std::variant<PaletteId, std::error_code>{ ec };
355	
356	        // 2) Cache in memory
357	        {
358	            std::unique_lock lock(self->cacheMutex_);
359	            self->memoryCache_[palette.id] = palette;
360	        }
361	
362	        // 3) Fire-and-forget remote push
363	        self->TriggerSync();
364	
365	        return std::variant<PaletteId, std::error_code>{ palette.id };
366	    });
367	}
