369	inline auto PaletteRepository::Load(const PaletteId& id) -> ResultFuture<std::optional<Palette>>
370	{
371	    return std::async(std::launch::async, [self = shared_from_this(), id]() -> std::variant<std::optional<Palette>, std::error_code>
372	    {
373	        {
374	            // Check in-memory cache first
375	            std::shared_lock lock(self->cacheMutex_);
376	            auto it = self->memoryCache_.find(id);
377	            if (it != self->memoryCache_.end())
378	                return std::optional<Palette>{ it->second };
379	        }
380	
381	        // Fallback to disk
